CREATE TABLE gifts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(120) NOT NULL, description VARCHAR(500) NOT NULL, category VARCHAR(80) NOT NULL, reserved BOOLEAN NOT NULL DEFAULT FALSE, guest_name VARCHAR(100), message VARCHAR(500));
